"WITH total_por_cliente AS (SELECT c.cliente_id, c.nome, SUM(i.quantidade * i.preco_unitario) AS total_gasto FROM clientes c JOIN pedidos p ON c.cliente_id = p.cliente_id JOIN itens_pedido i ON p.pedido_id = i.pedido_id GROUP BY c.cliente_id, c.nome), media_geral AS (SELECT AVG(total_gasto) AS media FROM total_por_cliente) SELECT t.nome, t.total_gasto FROM total_por_cliente t, media_geral m WHERE t.total_gasto > m.media;" 
